function Convert-ProjectPathToGalleryUrl([string]$ProjectPath) {
    return ('../../' + $ProjectPath.Replace('\\','/'))
}
function Encode([string]$Text) { return [System.Net.WebUtility]::HtmlEncode($Text) }
function New-AssetLink([string]$ProjectPath, [string]$Label, [bool]$Image) {
    if ([string]::IsNullOrWhiteSpace($ProjectPath)) { return '<div class="missing"><strong>후보 PNG 없음</strong><span>전용 원화가 없어 Window 상태 캡처로 확인합니다.</span></div>' }
    $url = Convert-ProjectPathToGalleryUrl $ProjectPath
    $exists = Test-Path -LiteralPath (Join-Path $ProjectRoot $ProjectPath) -PathType Leaf
    if (-not $exists) { return ('<div class="missing"><strong>누락 파일</strong><code>' + (Encode $ProjectPath) + '</code></div>') }
    if ($Image) { return ('<figure class="art-view"><a href="' + $url + '" target="_blank" rel="noopener" title="원본 PNG 열기"><img src="' + $url + '" alt="' + (Encode $Label) + ' 우향 후보"></a><figcaption>' + (Encode $Label) + ' · 우향</figcaption></figure>') }
    return ('<a class="file-link" href="' + $url + '" target="_blank" rel="noopener">' + (Encode $Label) + '</a>')
}

$cards = foreach ($r in $records) {
