    $safe = if ($r.Safe) { New-AssetLink $r.Safe ($r.Title + ' safe 파생본') $true } else { '' }
    $safeExists = $r.Safe -and (Test-Path -LiteralPath (Join-Path $ProjectRoot $r.Safe) -PathType Leaf)
