        '<div class="view-pair"><div class="facing"><div class="facing-label">우향 · 192px</div>' + $art + '</div><div class="facing"><div class="facing-label">좌향 · 192px 미러</div>' + $(if ($r.Art -and (Test-Path -LiteralPath (Join-Path $ProjectRoot $r.Art) -PathType Leaf)) { '<figure class="art-view mirrored"><a href="' + (Convert-ProjectPathToGalleryUrl $r.Art) + '" target="_blank" rel="noopener" title="원본 PNG 열기"><img src="' + (Convert-ProjectPathToGalleryUrl $r.Art) + '" alt="' + (Encode $r.Title) + ' 좌향 미러"></a><figcaption>좌향 비교용 반전</figcaption></figure>' } else { $art }) + '</div></div>'
    } elseif ($r.Id -eq 'turn' -and (Test-Path -LiteralPath (Join-Path $ProjectRoot $turnOriginal) -PathType Leaf)) { '<div class="missing large"><strong>절차적 turn 표현</strong><span>별도 원화 후보는 아래 미승인 후보 카드에 있습니다. 아직 본편 키포즈로 승인되지 않았습니다.</span></div>' } else { '<div class="missing large"><strong>전용 turn 후보 PNG 미확보</strong><span>절차적 turn 상태는 아래 Window 캡처와 근거 문서에서 확인하세요.</span></div>' }
    $safePanel = if ($safeExists) { '<details class="safe-detail"><summary>safe 파생본 보기</summary><div class="view-pair">' + $safe + '<figure class="art-view mirrored"><a href="' + (Convert-ProjectPathToGalleryUrl $r.Safe) + '" target="_blank" rel="noopener" title="safe 원본 PNG 열기"><img src="' + (Convert-ProjectPathToGalleryUrl $r.Safe) + '" alt="' + (Encode $r.Title) + ' safe 좌향"><figcaption>safe · 좌향 비교용 반전</figcaption></a></figure></div></details>' } elseif ($r.Safe) { '<details class="safe-detail"><summary>safe 파생본 보기</summary>' + $safe + '</details>' } else { '' }
    $evidence = foreach ($p in $r.Evidence) { New-AssetLink $p ([System.IO.Path]::GetFileName($p)) $false }
    $docs = foreach ($p in $r.Docs) { New-AssetLink $p ([System.IO.Path]::GetFileName($p)) $false }
    $badgeClass = if ($r.Approval -eq 'approved') { 'approved' } elseif ($r.Approval -eq 'procedural') { 'procedural' } else { 'pending' }
    $meta = '<span class="badge ' + $badgeClass + '">' + (Encode $r.Status) + '</span><span class="tag">' + (Encode $r.Group) + '</span>'
    $criteria = '<dl class="checks"><div><dt>Identity</dt><dd>' + (Encode $r.Identity) + '</dd></div><div><dt>접지 · anchor</dt><dd>' + (Encode $r.Ground) + '</dd></div><div><dt>프레임 팝</dt><dd>' + (Encode $r.Pop) + '</dd></div></dl>'
    '<article class="card" id="' + $r.Id + '" data-candidate="' + (Encode $r.Title) + '" data-status="' + $r.Approval + '" data-tags="' + (Encode $r.Tags) + '"><header class="card-head"><div><div class="eyebrow">' + (Encode $r.Group) + '</div><h3>' + (Encode $r.Title) + '</h3><p>' + (Encode $r.Note) + '</p></div><div class="badges">' + $meta + '</div></header>' + $images + $safePanel + $criteria + '<div class="links"><section><h4>Window · 비교 캡처</h4><div class="link-list">' + ($evidence -join '') + '</div></section><section><h4>근거 문서</h4><div class="link-list">' + ($docs -join '') + '</div></section></div><fieldset class="review-export"><legend>후보 검토 기록 · 임시 입력</legend><label>판정 제안<select class="proposal"><option>수용 제안</option><option>수정 요청</option><option>반려</option></select></label><label>근거<textarea class="reason" rows="3" placeholder="이 후보의 근거를 입력하세요."></textarea></label><div class="review-fields"><label>검수자<input class="reviewer" type="text" autocomplete="off" placeholder="검수자 이름"></label><label>검수 일시<input class="review-time" type="text" placeholder="비워두면 다운로드 시각과 시간대를 기록"></label></div><label>실제 화면 조건 (해상도·배율·방향)<input class="conditions" type="text" value="192×192 게임 캔버스, 좌우 방향 비교, 필요 시 최근접 3× 확대"></label><button class="download-review" type="button">이 후보 검수 기록 Markdown 다운로드</button><p class="export-note">새로고침하면 입력은 사라집니다. 버튼을 직접 눌렀을 때만 REVIEW_TEMPLATE 형식 파일을 내려받습니다. 수용 제안도 승인 자체가 아니며 이 갤러리는 승인 레지스트리를 변경하지 않습니다.</p></fieldset></article>'
}

